import com.example.productlab.model.Product;
import com.example.productlab.model.PurchaseOrder;
import com.example.productlab.repository.ProductRepository;
import com.example.productlab.repository.PurchaseOrderRepository;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
public class OrderService {
    private final ProductRepository products;
    private final PurchaseOrderRepository orders;
    public OrderService(ProductRepository products,
                        PurchaseOrderRepository orders) {
        this.products = products;
        this.orders = orders;
    }
    @Transactional
    public Long reserve(Long productId, int quantity) {
        if (quantity <= 0) throw new IllegalArgumentException("Quantity must be positive");
        Product product = products.findById(productId)
                .orElseThrow(() -> new IllegalArgumentException("Product not found"));
        if (product.getStock() < quantity) {
            throw new IllegalStateException("Insufficient stock");
        }
        product.setStock(product.getStock() - quantity);
        PurchaseOrder order = orders.save(new PurchaseOrder(productId, quantity));
        return order.getId();
    }
}

