package com.example.productlab.service;

public class QuantityPolicy {
    public int remaining(int available, int requested) {
        if (requested <= 0) throw new IllegalArgumentException("Quantity must be positive");
        if (requested > available) throw new IllegalStateException("Insufficient stock");
        return available - requested;
    }
}

