import com.example.productlab.model.*;
import com.example.productlab.repository.*;
import com.example.productlab.error.ProductNotFoundException;
import com.example.productlab.error.InsufficientStockException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
public class InventoryService {
    private final ProductRepository products;
    private final PurchaseOrderRepository orders;
    public InventoryService(ProductRepository products,
                            PurchaseOrderRepository orders) {
        this.products = products;
        this.orders = orders;
    }
    @Transactional
    public Long reserve(OrderRequest request) {
        Product product = products.findById(request.productId())
            .orElseThrow(() -> new ProductNotFoundException(request.productId()));
        if (request.quantity() <= 0) {
            throw new IllegalArgumentException("Quantity must be positive");
        }
        if (product.getStock() < request.quantity()) {
            throw new InsufficientStockException();
        }
        product.setStock(product.getStock() - request.quantity());
        return orders.save(new PurchaseOrder(product.getId(), request.quantity()))
                     .getId();
    }
}

